16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    /**
112	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
113	     * space, then the national digits (the digits after the country code) grouped in threes from
114	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
115	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
116	     *
117	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
118	     *         {@code null} or not a {@code +} followed by digits
119	     */
120	    public String getTelephoneDisplay() {
121	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
122	            return this.telephone;
123	        }
124	        String digits = this.telephone.substring(1);
125	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
126	        if (digits.length() <= countryCodeLength) {
127	            return this.telephone;
128	        }
129	        String countryCode = digits.substring(0, countryCodeLength);
130	        String national = digits.substring(countryCodeLength);
131	        StringBuilder grouped = new StringBuilder();
132	        for (int i = 0; i < national.length(); i++) {
133	            if (i > 0 && i % 3 == 0) {
134	                grouped.append(' ');
135	            }
136	            grouped.append(national.charAt(i));
137	        }
138	        return "+" + countryCode + " " + grouped;
139	    }
140	
141	    /**
142	     * The E.164 calling codes that are a single digit ({@code +1} for the North American Numbering
143	     * Plan and {@code +7} for the Russia/Kazakhstan zone); every other calling code is two digits.
144	     */
145	    private static final Set<String> ONE_DIGIT_CALLING_CODES = Set.of("1", "7");
146	
147	    public String getEmail() {
148	        return this.email;
149	    }
150	
151	    public void setEmail(String email) {
152	        this.email = email;
153	    }
154	
155	    public String getPostcode() {
156	        return this.postcode;
157	    }
158	
159	    public void setPostcode(String postcode) {
160	        this.postcode = postcode;
161	    }
162	
163	    public LocalDate getRegistrationDate() {
164	        return this.registrationDate;
165	    }
166	
167	    public void setRegistrationDate(LocalDate registrationDate) {
168	        this.registrationDate = registrationDate;
169	    }
170	
171	    public LocalDate getBirthDate() {
172	        return this.birthDate;
173	    }
174	
175	    public void setBirthDate(LocalDate birthDate) {
176	        this.birthDate = birthDate;
177	    }
178	
179	    /**
180	     * The owner's age band, derived from the {@link #birthDate} measured in completed years
181	     * against the {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
182	     * from 18 to 64, and {@code "SENIOR"} at 65 and over.
183	     *
184	     * @return the age band, or {@code null} when either the birth date or the registration
185	     *         date has not been assigned
186	     */
187	    public String getAgeBand() {
188	        if (this.birthDate == null || this.registrationDate == null) {
189	            return null;
190	        }
191	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
192	        if (age < 18) {
193	            return "MINOR";
194	        }
195	        if (age < 65) {
196	            return "ADULT";
197	        }
198	        return "SENIOR";
199	    }
200	
201	    public String getCustomerCode() {
202	        return this.customerCode;
203	    }
204	
205	    public void setCustomerCode(String customerCode) {
206	        this.customerCode = customerCode;
207	    }
208	
209	    public String getHouseholdId() {
210	        return this.householdId;
211	    }
212	
213	    public void setHouseholdId(String householdId) {
214	        this.householdId = householdId;
215	    }
216	
217	    public Integer getNamesakeCount() {
218	        return this.namesakeCount;
219	    }
220	
221	    public void setNamesakeCount(Integer namesakeCount) {
222	        this.namesakeCount = namesakeCount;
223	    }
224	
225	    /**
226	     * Whether more than 80 owners had already been created today at the time this owner
227	     * was created, indicating an unusually high signup volume.
228	     *
229	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
230	     *         {@code false} (never {@code null})
231	     */
232	    public Boolean getBulkSignupWarning() {
233	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
234	    }
235	
236	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
237	        this.bulkSignupWarning = bulkSignupWarning;
238	    }
239	
240	    /**
241	     * The number of owners in this owner's household (owners sharing the same
242	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
243	     * membership tier.
244	     *
245	     * @return the household member count, or {@code null} if it has not been assigned
246	     */
247	    public Integer getHouseholdSize() {
248	        return this.householdSize;
249	    }
250	
251	    public void setHouseholdSize(Integer householdSize) {
252	        this.householdSize = householdSize;
253	    }
254	
255	    /**
256	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
257	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
258	     *
259	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
260	     *         {@code false} (never {@code null})
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate != null && this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
269	
270	    /**
271	     * The id of the existing owner this owner may duplicate (same last name and postcode,
272	     * different telephone), or {@code null} when this owner is not a possible duplicate.
273	     *
274	     * @return the matching owner id, or {@code null}
275	     */
276	    public Integer getPossibleDuplicateOf() {
277	        return this.possibleDuplicateOf;
278	    }
279	
280	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
281	        this.possibleDuplicateOf = possibleDuplicateOf;
282	    }
283	
284	    /**
285	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
286	     *
287	     * @return the formatted display name
288	     */
289	    public String getDisplayName() {
290	        return this.getLastName() + ", " + this.getFirstName();
291	    }
292	
293	    /**
294	     * The owner's initials: the upper-cased first letters of the first and last
295	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
296	     *
297	     * @return the formatted initials
298	     */
299	    public String getInitials() {
300	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
301	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
302	    }
303	
304	    /**
305	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
306	     * {@code YY} is the last two digits of the registration date's year (e.g.
307	     * {@code "NSW-1A2B3C4D-M26"}).
308	     *
309	     * @return the formatted membership number, or {@code null} if the customer code or
310	     *         registration date has not been assigned
311	     */
312	    public String getMembershipNumber() {
313	        if (this.customerCode == null || this.registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
317	    }
318	
319	    /**
320	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
321	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
322	     * (non-digit characters are ignored).
323	     *
324	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
325	     */
326	    public Integer getCheckDigit() {
327	        if (this.customerCode == null) {
328	            return null;
329	        }
330	        int sum = 0;
331	        boolean dbl = true;
332	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
333	            char c = this.customerCode.charAt(i);
334	            if (c < '0' || c > '9') {
335	                continue;
336	            }
337	            int d = c - '0';
338	            if (dbl) {
339	                d *= 2;
340	                if (d > 9) {
341	                    d -= 9;
342	                }
343	            }
344	            sum += d;
345	            dbl = !dbl;
346	        }
347	        return (10 - (sum % 10)) % 10;
348	    }
349	
350	    /**
351	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
352	     * they carry an email address, {@code 1} when they have no namesakes
353	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
354	     * members ({@code householdSize}), and {@code 3} for tenure of more than {@code 365}
355	     * days (measured from the {@code registrationDate}). Because a newly created owner has
356	     * zero tenure, a new owner can score at most {@code 5} points.
357	     *
358	     * @return the membership points
359	     */
360	    public Integer getMembershipPoints() {
361	        int points = 0;
362	        boolean hasEmail = this.email != null && !this.email.isBlank();
363	        if (hasEmail) {
364	            points += 2;
365	        }
366	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
367	        if (noNamesakes) {
368	            points += 1;
369	        }
370	        if (this.householdSize != null && this.householdSize >= 3) {
371	            points += 2;
372	        }
373	        if (this.registrationDate != null
374	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
375	            points += 3;
376	        }
377	        return points;
378	    }
379	
380	    /**
381	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
382	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
383	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
384	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
385	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
386	     * is reserved for owners whose tenure exceeds {@code 365} days.
387	     *
388	     * @return the membership level
389	     */
390	    public Integer getMembershipLevel() {
391	        int points = getMembershipPoints();
392	        if (points >= 6) {
393	            return 4;
394	        }
395	        if (points >= 4) {
396	            return 3;
397	        }
398	        if (points >= 2) {
399	            return 2;
400	        }
401	        return 1;
402	    }
403	
404	    /**
405	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
406	     * email address, otherwise {@code "PHONE"}.
407	     *
408	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
409	     */
410	    public String getContactPreference() {
411	        boolean hasEmail = this.email != null && !this.email.isBlank();
412	        return hasEmail ? "EMAIL" : "PHONE";
413	    }
414	
415	    /**
416	     * The owner's identity key: the single derived value used for duplicate detection, formed as
417	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
418	     * email are the already-normalized stored values and a {@code null} email or household id is
419	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
420	     * are equal; because the telephone is part of the key, household members with different
421	     * telephones have different identity keys.
422	     *
423	     * @return the derived identity key
424	     */
425	    public String getIdentityKey() {
426	        String telephonePart = this.telephone == null ? "" : this.telephone;
427	        String emailPart = this.email == null ? "" : this.email;
428	        String householdPart = this.householdId == null ? "" : this.householdId;
429	        return telephonePart + "|" + emailPart + "|" + householdPart;
430	    }
431	
432	    /**
433	     * City -> canonical region, the fixed ground truth for deriving locality.
434	     */
435	    private static final Map<String, String> CITY_REGION = Map.of(
436	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
437	
438	    /**
439	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
440	     * deriving locality from the postcode ahead of the city.
441	     */
442	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
443	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
444	
445	    /**
446	     * The owner's locality: the canonical region resolved by the postcode range first
447	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
448	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
449	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
450	     * when the city is not in the table either. The postcode takes precedence so cities that share a
451	     * name are disambiguated by their postcode's region.
452	     *
453	     * @return the canonical region string, or {@code "UNKNOWN"}
454	     */
455	    public String getLocality() {
456	        String byPostcode = regionForPostcode(this.postcode);
457	        if (byPostcode != null) {
458	            return byPostcode;
459	        }
460	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
461	    }
462	
463	    /**
464	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
465	     * its locality.
466	     */
467	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
468	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
469	
470	    /**
471	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
472	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
473	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
474	     * (e.g. {@code "UNKNOWN"}).
475	     *
476	     * @return the IANA timezone name, or {@code null}
477	     */
478	    public String getTimezone() {
479	        return REGION_TIMEZONE.get(getLocality());
480	    }
481	
482	    /**
483	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
484	     * absent, not a 4-digit number, or in no known range.
485	     *
486	     * @param postcode the owner's postcode (may be {@code null})
487	     * @return the matching region, or {@code null}
488	     */
489	    private static String regionForPostcode(String postcode) {
490	        if (postcode == null || !postcode.matches("\\d{4}")) {
491	            return null;
492	        }
493	        int value = Integer.parseInt(postcode);
494	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
495	            int[] range = entry.getValue();
496	            if (value >= range[0] && value <= range[1]) {
497	                return entry.getKey();
498	            }
499	        }
500	        return null;
501	    }
502	
503	    protected Set<Pet> getPetsInternal() {
504	        if (this.pets == null) {
505	            this.pets = new HashSet<>();
506	        }
507	        return this.pets;
508	    }
509	
510	    protected void setPetsInternal(Set<Pet> pets) {
511	        this.pets = pets;
512	    }
513	
514	    public List<Pet> getPets() {
515	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
516	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
517	        return Collections.unmodifiableList(sortedPets);
518	    }
519	
520	    public void setPets(List<Pet> pets) {
521	        this.pets = new HashSet<>(pets);
522	    }
523	
524	    public void addPet(Pet pet) {
525	        getPetsInternal().add(pet);
526	        pet.setOwner(this);
527	    }
528	
529	    /**
530	     * Return the Pet with the given name, or null if none found for this Owner.
531	     *
532	     * @param name to test
533	     * @return true if pet name is already in use
534	     */
535	    public Pet getPet(String name) {
536	        return getPet(name, false);
537	    }
538	
539	    /**
540	     * Return the Pet with the given name, or null if none found for this Owner.
541	     *
542	     * @param name to test
543	     * @return true if pet name is already in use
544	     */
545	    public Pet getPet(String name, boolean ignoreNew) {
546	        name = name.toLowerCase();
547	        for (Pet pet : getPetsInternal()) {
548	            if (!ignoreNew || !pet.isNew()) {
549	                String compName = pet.getName();
550	                compName = compName.toLowerCase();
551	                if (compName.equals(name)) {
552	                    return pet;
553	                }
554	            }
555	        }
556	        return null;
557	    }
558	
559	    public Pet getPet(Integer petId) {
560	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
561	    }
562	
563	    @Override
564	    public String toString() {
565	        return new ToStringCreator(this)
566	
567	            .append("id", this.getId())
568	            .append("new", this.isNew())
569	            .append("lastName", this.getLastName())
570	            .append("firstName", this.getFirstName())
571	            .append("address", this.address)
572	            .append("city", this.city)
573	            .append("telephone", this.telephone)
574	            .append("email", this.email)
575	            .toString();
576	    }
577	}
