78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
80	
81	    /**
82	     * Disposable email domains that are refused: an owner whose email domain is on this blocklist
83	     * is rejected. The value is the already-normalized (trimmed, lower-cased) email's domain.
84	     */
85	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
86	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
87	
88	    /**
89	     * Common address abbreviations expanded to their full form during address normalization.
90	     * Matching is performed per whitespace-separated token on the upper-cased value.
91	     */
92	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
93	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
94	
95	    /**
96	     * Required national-number length (the digits after the country code) per E.164 country code.
97	     * A number whose country code appears here must carry exactly the mapped number of national
98	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
