106	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
107	     * any 4-digit postcode is accepted.
108	     */
109	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
110	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
