157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        LocalDate suppliedDate = owner.getRegistrationDate();
161	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
162	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
163	        }
164	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
165	        LocalDate registrationDate = toBusinessDay(effectiveDate);
166	        owner.setRegistrationDate(registrationDate);
167	        long createdToday = this.clinicService.findAllOwners().stream()
168	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
169	            .count();
170	        if (createdToday >= 100) {
171	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
172	        }
173	        owner.setBulkSignupWarning(createdToday > 80);
174	        String address = normalizeAddress(owner.getAddress());
175	        if (address == null || address.isEmpty()) {
176	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
177	        }
178	        owner.setAddress(address);
179	        String telephone = toE164(owner.getTelephone());
180	        if (telephone == null) {
