195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        String cityKey = householdKey(owner.getCity());
198	        long cityCount = this.clinicService.findAllOwners().stream()
199	            .filter(existing -> existing.getCity() != null
200	                && cityKey.equals(householdKey(existing.getCity())))
201	            .count();
202	        if (cityCount >= 50) {
203	            return new ResponseEntity<>(HttpStatus.CONFLICT);
204	        }
205	        // The household is keyed on (normalized last name, postcode): every owner derives the same
206	        // deterministic householdId from those two fields, so owners sharing them are the same
207	        // household. This computed id is what duplicate detection and the household size below key off.
208	        String householdId = householdId(owner);
209	        owner.setHouseholdId(householdId);
210	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
211	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
212	            .toList();
213	        owner.setHouseholdSize(householdMembers.size() + 1);
214	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
215	        // Household-duplicate block: a second owner in an existing household (same computed
216	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
217	        // declaring the new owner a member — rather than creating the household link itself.
218	        if (!householdMembers.isEmpty() && !sharesHousehold) {
219	            return new ResponseEntity<>(HttpStatus.CONFLICT);
220	        }
221	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
222	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
223	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
224	        // telephone is part of the key, two household members with different telephones are allowed.
225	        // This still catches a full identity repeat even when it declares sharesHousehold.
226	        String identityKey = owner.getIdentityKey();
227	        boolean identityInUse = this.clinicService.findAllOwners().stream()
228	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
229	        if (identityInUse) {
230	            return new ResponseEntity<>(HttpStatus.CONFLICT);
231	        }
232	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
233	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
234	        // different telephone is now, by definition, a household duplicate already rejected above, so
235	        // it never reaches this point; the check is retained for owners that are not household matches.
236	        if (sharesHousehold) {
237	            owner.setPossibleDuplicate(false);
238	        } else {
239	            String softDuplicateLastNameKey = householdKey(owner.getLastName());
240	            String softDuplicatePostcode = owner.getPostcode();
241	            String softDuplicateTelephone = owner.getTelephone();
242	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
243	                : this.clinicService.findAllOwners().stream()
244	                    .filter(existing -> softDuplicateLastNameKey.equals(householdKey(existing.getLastName())))
245	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
246	                    .filter(existing -> !softDuplicateTelephone.equals(existing.getTelephone()))
247	                    .min(Comparator.comparing(Owner::getId))
248	                    .orElse(null);
249	            if (possibleDuplicate != null) {
250	                owner.setPossibleDuplicate(true);
251	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
252	            } else {
253	                owner.setPossibleDuplicate(false);
254	            }
255	        }
256	        owner.setCustomerCode(customerCode(owner));
257	        String firstNameKey = householdKey(owner.getFirstName());
258	        String namesakeLastNameKey = householdKey(owner.getLastName());
259	        long namesakeCount = this.clinicService.findAllOwners().stream()
260	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
261	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
262	            .count();
263	        owner.setNamesakeCount((int) namesakeCount);
264	        this.clinicService.saveOwner(owner);
265	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
266	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
267	            owner.getMembershipLevel(), owner.getMembershipNumber());
268	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
269	        headers.setLocation(UriComponentsBuilder.newInstance()
270	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
271	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
272	    }
273	
274	    /**
275	     * Validates an owner's postcode against the region derived from its city. The postcode is
276	     * optional: a {@code null} value is always accepted. When present it must fall within the
277	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
278	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
279	     * The 4-digit syntax itself is enforced upstream by bean validation.
280	     *
281	     * @param postcode the owner's postcode (may be {@code null})
282	     * @param locality the region derived from the owner's city
283	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
284	     *         within the region's range; {@code false} when it is out of range
285	     */
286	    private boolean isPostcodeValidForCity(String postcode, String locality) {
287	        if (postcode == null) {
288	            return true;
289	        }
290	        int[] range = REGION_POSTCODES.get(locality);
291	        if (range == null) {
292	            return true;
293	        }
294	        int value = Integer.parseInt(postcode);
295	        return value >= range[0] && value <= range[1];
296	    }
297	
298	    /**
299	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
300	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
301	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
302	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
303	     * recognised country codes the national number (the digits after the country code) must also be
304	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
305	     * needs 10); a wrong national-number length yields {@code null}.
306	     *
307	     * @param telephone the raw telephone value (may be {@code null})
308	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
309	     *         a valid E.164 number
310	     */
311	    private String toE164(String telephone) {
312	        if (telephone == null) {
313	            return null;
314	        }
315	        String trimmed = telephone.trim();
316	        boolean hasCountryCode = trimmed.startsWith("+");
317	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
318	        if (hasCountryCode) {
319	            cleaned = cleaned.substring(1);
320	        }
321	        if (!cleaned.matches("[0-9]+")) {
322	            return null;
323	        }
324	        String digits;
325	        if (hasCountryCode) {
326	            digits = cleaned;
327	        } else {
328	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
329	            digits = "61" + national;
330	        }
331	        if (digits.length() < 8 || digits.length() > 15) {
332	            return null;
333	        }
334	        if (!hasValidNationalNumberLength(digits)) {
335	            return null;
336	        }
337	        return "+" + digits;
338	    }
339	
340	    /**
341	     * Checks the national-number length of an E.164 digit string (country code plus national
342	     * number, without the leading {@code '+'}) against its country code. When the number's country
343	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
344	     * country code must number exactly what that country requires; the longest matching country
345	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
346	     * only by the generic total-length rule).
347	     *
348	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
349	     * @return {@code true} if the national-number length is acceptable for the country code
350	     */
351	    private boolean hasValidNationalNumberLength(String digits) {
352	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
353	            .filter(entry -> digits.startsWith(entry.getKey()))
354	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
355	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
356	            .orElse(true);
357	    }
358	
359	    /**
360	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
361	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
362	     *
363	     * @param email the raw email value (must not be {@code null})
364	     * @return the trimmed, lower-cased email
365	     */
366	    private String normalizeEmail(String email) {
367	        return email.trim().toLowerCase(Locale.ROOT);
368	    }
369	
370	    /**
371	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
372	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
373	     * an email without an {@code '@'} carries no blocked domain.
374	     *
375	     * @param email the trimmed, lower-cased email
376	     * @return {@code true} when the email's domain is blocklisted
377	     */
378	    private boolean isDisposableEmailDomain(String email) {
379	        int at = email.lastIndexOf('@');
380	        if (at < 0) {
381	            return false;
382	        }
383	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
384	    }
385	
386	    /**
387	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
388	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
389	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
390	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
391	     * normalized form, and every household comparison uses it.
392	     *
393	     * @param address the raw address value (may be {@code null})
394	     * @return the normalized address, or {@code null} if the input was {@code null}
395	     */
396	    private String normalizeAddress(String address) {
397	        if (address == null) {
398	            return null;
399	        }
400	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
401	        if (collapsed.isEmpty()) {
402	            return collapsed;
403	        }
404	        String[] tokens = collapsed.split(" ");
405	        StringBuilder sb = new StringBuilder(collapsed.length());
406	        for (int i = 0; i < tokens.length; i++) {
407	            if (i > 0) {
408	                sb.append(' ');
409	            }
410	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
411	        }
412	        return sb.toString();
413	    }
414	
415	    /**
416	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
417	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
418	     * so that owners are compared case-insensitively with collapsed whitespace.
419	     *
420	     * @param value the raw value (must not be {@code null})
421	     * @return the normalized comparison key
422	     */
423	    private String householdKey(String value) {
424	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
425	    }
426	
427	    /**
428	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
429	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
430	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
431	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
432	     * those two fields derives the identical identifier and therefore belongs to the same household.
433	     *
434	     * @param owner the owner whose household identifier is derived
435	     * @return the stable household identifier
436	     */
437	    private String householdId(Owner owner) {
438	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
439	        String key = householdKey(owner.getLastName()) + "|" + postcode;
440	        try {
441	            byte[] digest = MessageDigest.getInstance("SHA-256")
442	                .digest(key.getBytes(StandardCharsets.UTF_8));
443	            StringBuilder sb = new StringBuilder(digest.length * 2);
444	            for (byte b : digest) {
445	                sb.append(String.format("%02x", b));
446	            }
447	            return sb.substring(0, 12);
448	        }
449	        catch (java.security.NoSuchAlgorithmException e) {
450	            throw new IllegalStateException("SHA-256 not available", e);
451	        }
452	    }
453	
454	    /**
455	     * Builds the customer code for a newly registered owner in the form
456	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
457	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
458	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
459	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
460	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). When the computed code
461	     * collides with an existing owner's customer code, {@code '-<n>'} is appended using the
462	     * smallest {@code n} of 2 or more that makes the result unique, guaranteeing distinct owners
463	     * always receive distinct customer codes.
464	     *
465	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
466	     * @return the assigned customer code
467	     */
468	    private String customerCode(Owner owner) {
469	        String region = owner.getLocality();
470	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
471	        String base = region + "-" + hash8;
472	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
473	            .map(Owner::getCustomerCode)
474	            .filter(code -> code != null)
475	            .collect(Collectors.toSet());
476	        if (!existingCodes.contains(base)) {
477	            return base;
478	        }
479	        int n = 2;
480	        while (existingCodes.contains(base + "-" + n)) {
481	            n++;
482	        }
483	        return base + "-" + n;
484	    }
485	
486	    /**
487	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
488	     * UTF-8 bytes of {@code input}.
489	     *
490	     * @param input  the value to hash
491	     * @param length the number of leading hex characters to keep
492	     * @return the truncated, upper-cased hex digest
493	     */
494	    private String sha256UpperHex(String input, int length) {
495	        try {
496	            byte[] digest = MessageDigest.getInstance("SHA-256")
497	                .digest(input.getBytes(StandardCharsets.UTF_8));
498	            StringBuilder sb = new StringBuilder(digest.length * 2);
499	            for (byte b : digest) {
500	                sb.append(String.format("%02x", b));
501	            }
502	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
503	        }
504	        catch (java.security.NoSuchAlgorithmException e) {
505	            throw new IllegalStateException("SHA-256 not available", e);
506	        }
507	    }
508	
509	    /**
510	     * Rolls a registration date forward onto a business day. When the given date falls on a
511	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
512	     *
513	     * @param date the effective registration date (must not be {@code null})
514	     * @return the same date if it is a weekday, otherwise the next Monday
515	     */
516	    private LocalDate toBusinessDay(LocalDate date) {
517	        DayOfWeek dayOfWeek = date.getDayOfWeek();
518	        if (dayOfWeek == DayOfWeek.SATURDAY) {
519	            return date.plusDays(2);
520	        }
521	        if (dayOfWeek == DayOfWeek.SUNDAY) {
522	            return date.plusDays(1);
523	        }
524	        return date;
525	    }
526	
527	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
528	    @Override
529	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
530	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
531	        if (currentOwner == null) {
532	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
533	        }
534	        String email = ownerFieldsDto.getEmail();
535	        if (email != null) {
536	            email = normalizeEmail(email);
537	            if (!EMAIL_PATTERN.matcher(email).matches()) {
538	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
539	            }
540	        }
541	        String telephone = toE164(ownerFieldsDto.getTelephone());
542	        if (telephone == null) {
543	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
544	        }
545	        currentOwner.setAddress(ownerFieldsDto.getAddress());
546	        currentOwner.setCity(ownerFieldsDto.getCity());
547	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
548	        currentOwner.setLastName(ownerFieldsDto.getLastName());
549	        currentOwner.setTelephone(telephone);
550	        currentOwner.setEmail(email);
551	        this.clinicService.saveOwner(currentOwner);
552	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
553	    }
554	
555	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
556	    @Transactional
557	    @Override
558	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
559	        Owner owner = this.clinicService.findOwnerById(ownerId);
560	        if (owner == null) {
561	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
562	        }
563	        this.clinicService.deleteOwner(owner);
564	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
570	        Owner owner = this.clinicService.findOwnerById(ownerId);
571	        if (owner == null) {
572	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
573	        }
574	        HttpHeaders headers = new HttpHeaders();
575	        Pet pet = petMapper.toPet(petFieldsDto);
576	        owner.setId(ownerId);
577	        pet.setOwner(owner);
578	        pet.getType().setName(null);
579	        this.clinicService.savePet(pet);
580	        PetDto petDto = petMapper.toPetDto(pet);
581	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
582	            .buildAndExpand(pet.getId()).toUri());
583	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
584	    }
585	
586	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
587	    @Override
588	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
589	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
590	        if (currentOwner != null) {
591	            Pet currentPet = this.clinicService.findPetById(petId);
592	            if (currentPet != null) {
593	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
594	                currentPet.setName(petFieldsDto.getName());
595	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
596	                this.clinicService.savePet(currentPet);
597	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
598	            }
599	        }
600	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
601	    }
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
606	        HttpHeaders headers = new HttpHeaders();
607	        Visit visit = visitMapper.toVisit(visitFieldsDto);
608	        Pet pet = new Pet();
609	        pet.setId(petId);
610	        visit.setPet(pet);
611	        this.clinicService.saveVisit(visit);
612	        VisitDto visitDto = visitMapper.toVisitDto(visit);
613	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
614	            .buildAndExpand(visit.getId()).toUri());
615	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
616	    }
617	
618	
619	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
620	    @Override
621	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
622	        Owner owner = this.clinicService.findOwnerById(ownerId);
623	        if (owner != null) {
624	            Pet pet = owner.getPet(petId);
625	            if (pet != null) {
626	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
627	            }
628	        }
629	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
630	    }
631	}
